#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "correlation.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto n_vec = noarr::vector<'n'>();
constexpr auto m_vec = noarr::vector<'m'>();
constexpr auto p_vec = noarr::vector<'p'>();
constexpr auto q_vec = noarr::vector<'q'>();

struct tuning {
	// data: n x m  (rows: n, columns/features: m), row-major (m contiguous)
	DEFINE_PROTO_STRUCT(data_layout, m_vec ^ n_vec);
	// corr: p x q (both run over features 0..M-1), row-major (q contiguous)
	DEFINE_PROTO_STRUCT(corr_layout, q_vec ^ p_vec);
	// 1D vectors over features
	DEFINE_PROTO_STRUCT(vec_layout, m_vec);
} tuning;


// initialization function
// float_n <- N (number of rows in data)
// data[i][j] = (DATA_TYPE)(i*j)/M + i;
void init_array(num_t &float_n, auto data) {
	using namespace noarr;

	// N is the length in the 'n' dimension
	auto n_len = data | get_length<'n'>();
	float_n = static_cast<num_t>(n_len);

	// M is the length in the 'm' dimension (pre-computed once, not per element)
	auto m_len = data | get_length<'m'>();
	const num_t M_len = static_cast<num_t>(m_len);

	// Traverse row-major: 'n' outer, 'm' inner. This already matches the layout.
	traverser(data).for_each([&](auto state) {
		auto [i, j] = get_indices<'n', 'm'>(state);

		data[state] =
			static_cast<num_t>(
				static_cast<num_t>(i * j) / M_len +
				static_cast<num_t>(i));
	});
}


// main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_correlation(num_t float_n, auto data, auto corr, auto mean, auto stddev) {
	using namespace noarr;

	const num_t eps          = SCALAR_VAL(0.1);
	const num_t inv_float_n  = SCALAR_VAL(1.0) / float_n;
	const num_t sqrt_float_n = SQRT_FUN(float_n);

#pragma scop

	// ------------------------------------------------------------------------
	// mean[j] = 1/N * sum_i data[i][j]
	//
	// Optimized for row-major layout:
	//  1. zero mean[j]
	//  2. accumulate row by row (inner loop over contiguous 'm')
	// ------------------------------------------------------------------------

	// 1) mean[j] = 0
	traverser(mean).for_each([&](auto s_m) {
		mean[s_m] = SCALAR_VAL(0.0);
	});

	// 2) accumulate over rows: for each row i, walk contiguous features j
	traverser(data, mean).template for_dims<'n'>([&](auto trav_n) {
		// trav_n has 'n' fixed, iterates over 'm'
		trav_n.for_each([&](auto state) {
			// state has 'n' and 'm'; mean ignores 'n'
			mean[state] += data[state];
		});
	});

	// 3) scale by 1/N
	traverser(mean).for_each([&](auto s_m) {
		mean[s_m] *= inv_float_n;
	});

	// ------------------------------------------------------------------------
	// stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	// stddev[j] = 1.0 if stddev[j] <= eps
	//
	// Also done row-major for better locality:
	//  1. zero stddev[j]
	//  2. accumulate squared differences row by row
	//  3. finalize: divide by N, sqrt, clamp by eps
	// ------------------------------------------------------------------------

	// 1) stddev[j] = 0
	traverser(stddev).for_each([&](auto s_m) {
		stddev[s_m] = SCALAR_VAL(0.0);
	});

	// 2) accumulate (data[i][j] - mean[j])^2 row by row
	traverser(data, mean, stddev).template for_dims<'n'>([&](auto trav_n) {
		// trav_n has 'n' fixed, iterates over 'm'
		trav_n.for_each([&](auto state) {
			num_t val = data[state] - mean[state];
			stddev[state] += val * val;
		});
	});

	// 3) finalize stddev[j]
	traverser(stddev).for_each([&](auto s_m) {
		stddev[s_m] = SQRT_FUN(stddev[s_m] * inv_float_n);
		stddev[s_m] = (stddev[s_m] <= eps) ? SCALAR_VAL(1.0) : stddev[s_m];
	});

	// ------------------------------------------------------------------------
	// Center and reduce the column vectors:
	//   data[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
	//
	// We precompute sqrt(float_n) once and reuse it inside the loops.
	// Traversal is row-major (n outer, m inner) to match data layout.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'n'>([&](auto trav_n) {
		// trav_n has 'n' fixed; iterate over 'm'
		trav_n.for_each([&](auto state) {
			num_t centered = data[state] - mean[state];
			data[state] = centered / (sqrt_float_n * stddev[state]);
		});
	});

	// ------------------------------------------------------------------------
	// Compute the m x m correlation matrix:
	//
	// for (i = 0; i < M-1; i++) {
	//   corr[i][i] = 1.0;
	//   for (j = i+1; j < M; j++) {
	//     corr[i][j] = 0.0;
	//     for (k = 0; k < N; k++)
	//       corr[i][j] += data[k][i] * data[k][j];
	//     corr[j][i] = corr[i][j];
	//   }
	// }
	// corr[M-1][M-1] = 1.0;
	//
	// Optimizations:
	//  - Use a single multi-structure traverser over (data_p, data_q, corr)
	//    instead of constructing a new traverser per (i,j) pair.
	//  - Accumulate into a scalar register 'sum' and write corr[i][j] once.
	// ------------------------------------------------------------------------

	std::size_t m_len = corr | get_length<'p'>(); // M

	// Create views on data so that the feature index matches corr's 'p'/'q'
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

	// A single traverser over all three structures: dimensions {n, p, q}
	auto trav_all = traverser(data_p, data_q, corr);

	// Outer loop over i = 0 .. M-1 (dimension 'p')
	trav_all.template for_dims<'p'>([&](auto trav_p) {
		auto state_p = trav_p.state();
		auto i = noarr::get_index<'p'>(state_p);

		// Only i < M-1 participate in the nested j-loop
		if (i < m_len - 1) {
			// corr[i][i] = 1.0;
			corr[noarr::idx<'p', 'q'>(i, i)] = SCALAR_VAL(1.0);

			// Middle loop over j = 0 .. M-1 (dimension 'q'), we only use j > i
			trav_p.template for_dims<'q'>([&](auto trav_pq) {
				auto state_pq = trav_pq.state();
				auto j = noarr::get_index<'q'>(state_pq);

				if (j > i) {
					// Accumulate corr[i][j] in a scalar to reduce memory traffic
					num_t sum = SCALAR_VAL(0.0);

					// Inner loop over k = 0 .. N-1 (dimension 'n')
					// 'p' and 'q' are fixed by trav_pq; for_each iterates only 'n'.
					trav_pq.for_each([&](auto state_n) {
						// state_n has 'n' (varying) and fixed 'p','q' for indexing
						sum += data_p[state_n] * data_q[state_n];
					});

					// Write the result and exploit symmetry: corr[j][i] = corr[i][j]
					corr[state_pq] = sum;
					corr[noarr::idx<'p', 'q'>(j, i)] = sum;
				}
			});
		}
	});

	// Final diagonal element: corr[M-1][M-1] = 1.0;
	if (m_len > 0) {
		auto last = m_len - 1;
		corr[noarr::idx<'p', 'q'>(last, last)] = SCALAR_VAL(1.0);
	}

#pragma endscop
}

} // namespace

