	// Compute the m x m correlation matrix:
	//
	//   for (i = 0; i < M-1; i++) {
	//     corr[i][i] = 1.0;
	//     for (j = i+1; j < M; j++) {
	//       corr[i][j] = 0.0;
	//       for (k = 0; k < N; k++)
	//         corr[i][j] += data[k][i] * data[k][j];
	//       corr[j][i] = corr[i][j];
	//     }
	//   }
	//   corr[M-1][M-1] = 1.0;
	//
	// Optimized version:
	//   - First, zero the whole corr matrix.
	//   - Then accumulate the upper triangle using a k–i–j loop order:
	//       for each row k:
	//         for i:
	//           x_i = data[k][i];        // loaded once per (k,i)
	//           for j > i:
	//             corr[i][j] += x_i * data[k][j];
	//     This keeps data accesses row-major (contiguous in 'm') and
	//     reuses x_i from registers inside the inner j-loop.
	//   - Finally, set diag to 1.0 and copy the upper triangle to the lower.
	// ------------------------------------------------------------------------

	const std::size_t m_len = corr | get_length<'p'>(); // M

	// Quick exit for degenerate case
	if (m_len == 0) {
		// Nothing to do
#pragma endscop
		return;
	}

	// Zero the whole correlation matrix
	traverser(corr).for_each([&](auto state) {
		corr[state] = SCALAR_VAL(0.0);
	});

	// Create views on data so that the feature index matches corr's 'p'/'q'
	//   data_p: dims 'p','n' (feature-as-'p')
	//   data_q: dims 'q','n' (feature-as-'q')
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'p', 'n'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'q', 'n'

	// Accumulate upper triangle: k-i-j loop order expressed using traversers
	noarr::traverser(data_p, data_q, corr)
		.template for_dims<'n'>([&](auto trav_n) {
			// trav_n has 'n' fixed (one row k), 'p' and 'q' are free
			trav_n.template for_dims<'p'>([&](auto trav_np) {
				auto state_np = trav_np.state();
				const std::size_t i = noarr::get_index<'p'>(state_np);

				// For the last column, there is no j > i
				if (i + 1 >= m_len)
					return;

				// Load data[k][i] once per (k, i) and reuse inside inner loop
				const num_t x_i = data_p[state_np];

				trav_np.template for_dims<'q'>([&](auto trav_npq) {
					auto state_npq = trav_npq.state();
					const std::size_t j = noarr::get_index<'q'>(state_npq);

					if (j > i) {
						// state_npq has 'n','p','q':
						//   - corr uses 'p','q' (ignores 'n')
						//   - data_q uses 'q','n' (ignores 'p')
						corr[state_npq] += x_i * data_q[state_npq];
					}
				});
			});
		});

	// Enforce symmetry and set the diagonal to 1.0
	noarr::traverser(corr).template for_dims<'p'>([&](auto trav_p) {
		auto state_p = trav_p.state();
		const std::size_t i = noarr::get_index<'p'>(state_p);

		// Diagonal
		corr[noarr::idx<'p', 'q'>(i, i)] = SCALAR_VAL(1.0);

		// Lower triangle: corr[j][i] = corr[i][j]
		trav_p.template for_dims<'q'>([&](auto trav_pq) {
			auto state_pq = trav_pq.state();
			const std::size_t j = noarr::get_index<'q'>(state_pq);

			if (j > i) {
				const auto state_qp = noarr::idx<'p', 'q'>(j, i);
				corr[state_qp] = corr[state_pq];
			}
		});
	});

#pragma endscop
}

} // namespace

