	const num_t inv_float_n  = SCALAR_VAL(1.0) / float_n;
	const num_t sqrt_float_n = SQRT_FUN(float_n);

#pragma scop

	// ------------------------------------------------------------------------
	// 1) mean[j] = 1/N * sum_i data[i][j]
	//
	// Implemented as a row-major traversal (iterate 'n' outer, 'm' inner)
	// to improve spatial locality compared to the original column-wise scheme.
	// ------------------------------------------------------------------------

	// Initialize mean[j] = 0
	traverser(mean).for_each([=](auto state_m) {
		mean[state_m] = SCALAR_VAL(0.0);
	});

