	traverser(data, mean).template for_dims<'n'>([=](auto trav_n) {
		// trav_n has 'n' fixed; iterate over 'm' (features) in this row
		trav_n.template for_each<'m'>([=](auto state) {
			// state has 'n' and 'm'; mean ignores 'n'
			mean[state] += data[state];
		});
	});

	// Scale by 1/N
	traverser(mean).for_each([=](auto state_m) {
		mean[state_m] *= inv_float_n;
	});

	// ------------------------------------------------------------------------
	// 2) stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	//    stddev[j] = 1.0 if stddev[j] <= eps
	//
	// Also done in a row-major fashion to keep memory access contiguous.
	// ------------------------------------------------------------------------

	// Initialize stddev[j] = 0
	traverser(stddev).for_each([=](auto state_m) {
		stddev[state_m] = SCALAR_VAL(0.0);
