	// 3) Center and reduce the column vectors:
	//    data[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
	//
	// Again, traverse row-major to touch each row contiguously.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'n'>([=](auto trav_n) {
