	//         corr[j][i] = corr[i][j];
	//       }
	//     }
	//   }
	//
	// Implemented using a single multi-structure traverser over:
	//   - data_p : dims 'n','p' (data with feature dimension renamed to 'p')
	//   - data_q : dims 'n','q' (data with feature dimension renamed to 'q')
	//   - corr   : dims 'p','q'
	//
	// Outer `for_dims<'p','q'>` enumerates all (i,j) pairs.
	// Inner `for_each` iterates k over 'n' for each pair (i,j).
	// ------------------------------------------------------------------------

	// Create views on data so that feature index matches corr's 'p'/'q'
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

	noarr::traverser(data_p, data_q, corr).template for_dims<'p', 'q'>([=](auto trav_pq) {
		auto state_pq = trav_pq.state();
		auto i = noarr::get_index<'p'>(state_pq);
		auto j = noarr::get_index<'q'>(state_pq);

		if (i == j) {
			// Diagonal elements: corr[i][i] = 1.0
			corr[state_pq] = SCALAR_VAL(1.0);
