	// Optimization:
	//   We compute variance in a row-major pass, then:
	//     sigma_j = max(stddev[j], eps)  (with eps rule)
	//     stddev[j] <- 1 / (sqrt(N) * sigma_j)
	//   i.e. we turn stddev[] into per-feature scaling factors used below.
	// ------------------------------------------------------------------------

